<?php
/** A public conversation surface; $state contains only service projections. */
defined( 'ABSPATH' ) || exit;
$filters = $state['filters'];
$thread = $state['thread'];
$feed = self::feed_html( $state );
$selected_channel = $thread ? $thread['channel'] : $filters['channel'];
$channel_label = $state['channels'][ $selected_channel ] ?? __( 'All channels', 'petish-passport' );
$login = wp_login_url( self::url( $filters ) );
$can_reply = $thread && ! empty( $thread['can_reply'] );
$can_compose = $state['signed_in'] && $state['can_post'] && ( ! $thread || $can_reply );
?>
<main class="petish-chat" data-pet-chat data-chat-context="<?php echo esc_attr( $state['context'] ); ?>" data-chat-session="<?php echo esc_attr( $state['session'] ); ?>" data-chat-revision="<?php echo esc_attr( hash( 'sha256', $feed ) ); ?>" data-chat-signed-in="<?php echo $state['signed_in'] ? '1' : '0'; ?>" data-chat-filters="<?php echo esc_attr( wp_json_encode( $filters ) ); ?>" data-chat-interval="<?php echo $thread ? '15000' : '30000'; ?>">
    <a class="pch-skip" href="#chat-feed"><?php esc_html_e( 'Skip to conversations', 'petish-passport' ); ?></a>
    <header class="pch-heading">
        <div><p class="pch-eyebrow"><?php esc_html_e( 'Petish community', 'petish-passport' ); ?></p><h1><?php esc_html_e( 'Pet Chat', 'petish-passport' ); ?><span aria-hidden="true">.</span></h1><p class="pch-intro"><?php esc_html_e( 'Little questions. Shared discoveries. Good company.', 'petish-passport' ); ?></p></div>
        <div class="pch-heading-links"><a href="<?php echo esc_url( class_exists( 'Petish_Passport_Community' ) ? Petish_Passport_Community::url() : home_url( '/' ) ); ?>"><?php esc_html_e( 'Meet Pet Club', 'petish-passport' ); ?> <span aria-hidden="true">↗</span></a><a class="pch-button" href="<?php echo esc_url( $thread ? self::url( array( 'channel' => $thread['channel'] ), 'chat-composer' ) : '#chat-composer' ); ?>"><?php esc_html_e( 'Start a conversation', 'petish-passport' ); ?></a></div>
    </header>
    <?php if ( $state['notice'] ) : ?><p class="pch-notice" role="status"><?php echo esc_html( $state['notice'] ); ?></p><?php endif; ?>
    <?php if ( $state['error'] ) : ?><div class="pch-error" role="alert"><strong><?php esc_html_e( 'Your message has not been sent.', 'petish-passport' ); ?></strong><p><?php echo esc_html( $state['error'] ); ?></p><a href="#chat-composer"><?php esc_html_e( 'Check your draft', 'petish-passport' ); ?></a></div><?php endif; ?>
    <div class="pch-layout">
        <aside class="pch-sidebar">
            <nav class="pch-channels" aria-label="<?php esc_attr_e( 'Pet Chat channels', 'petish-passport' ); ?>" data-chat-channels>
                <h2><?php esc_html_e( 'Find your corner', 'petish-passport' ); ?></h2>
                <ul><li><a href="<?php echo esc_url( self::url() ); ?>" <?php if ( ! $selected_channel ) echo 'aria-current="page"'; ?>><span class="pch-channel-symbol" aria-hidden="true">#</span><?php esc_html_e( 'All conversations', 'petish-passport' ); ?></a></li>
                <?php foreach ( $state['channels'] as $slug => $label ) : ?><li><a href="<?php echo esc_url( self::url( array( 'channel' => $slug ) ) ); ?>" <?php if ( $selected_channel === $slug ) echo 'aria-current="page"'; ?>><span class="pch-channel-symbol" aria-hidden="true">#</span><?php echo esc_html( $label ); ?></a></li><?php endforeach; ?></ul>
            </nav>
            <details class="pch-mobile-channels"><summary><?php echo esc_html( $channel_label ); ?><span aria-hidden="true">⌄</span></summary><nav aria-label="<?php esc_attr_e( 'Choose a Pet Chat channel', 'petish-passport' ); ?>"><a href="<?php echo esc_url( self::url() ); ?>"><?php esc_html_e( 'All conversations', 'petish-passport' ); ?></a><?php foreach ( $state['channels'] as $slug => $label ) : ?><a href="<?php echo esc_url( self::url( array( 'channel' => $slug ) ) ); ?>" <?php if ( $selected_channel === $slug ) echo 'aria-current="page"'; ?>><?php echo esc_html( $label ); ?></a><?php endforeach; ?></nav></details>
            <section class="pch-community-note"><span aria-hidden="true">✦</span><h2><?php esc_html_e( 'A kinder kind of corner.', 'petish-passport' ); ?></h2><p><?php esc_html_e( 'Be welcoming, share your experience and respect each other’s privacy.', 'petish-passport' ); ?></p><p><?php esc_html_e( 'For urgent health concerns, contact a veterinarian.', 'petish-passport' ); ?></p></section>
        </aside>
        <div class="pch-main">
            <div class="pch-feed-heading"><div><?php if ( $thread ) : ?><a class="pch-back" href="<?php echo esc_url( self::url( array( 'channel' => $thread['channel'] ) ) ); ?>">← <?php echo esc_html( $channel_label ); ?></a><?php else : ?><h2><?php echo esc_html( $channel_label ); ?></h2><p><?php esc_html_e( 'Ask a question or share something worth passing on.', 'petish-passport' ); ?></p><?php endif; ?></div>
                <button class="pch-text-button" type="button" data-chat-poll-toggle aria-pressed="false" hidden><?php esc_html_e( 'Pause updates', 'petish-passport' ); ?></button></div>
            <?php if ( ! $thread ) : ?><nav class="pch-views" aria-label="<?php esc_attr_e( 'Conversation views', 'petish-passport' ); ?>"><?php foreach ( array( 'latest' => __( 'Latest', 'petish-passport' ), 'unanswered' => __( 'Open questions', 'petish-passport' ), 'answered' => __( 'Answered', 'petish-passport' ) ) as $view => $label ) : ?><a href="<?php echo esc_url( self::url( array( 'channel' => $filters['channel'], 'view' => $view ) ) ); ?>" <?php if ( $filters['view'] === $view ) echo 'aria-current="page"'; ?>><?php echo esc_html( $label ); ?></a><?php endforeach; ?></nav><?php endif; ?>
            <div class="pch-update-bar"><p class="pch-live-status" data-chat-status role="status" aria-live="polite" aria-atomic="true"></p><button type="button" class="pch-button pch-button-secondary" data-chat-update hidden><?php esc_html_e( 'Show new updates', 'petish-passport' ); ?></button></div>
            <section id="chat-feed" class="pch-feed" data-chat-feed aria-label="<?php echo esc_attr( $thread ? __( 'Conversation and replies', 'petish-passport' ) : __( 'Conversations', 'petish-passport' ) ); ?>" tabindex="-1"><?php echo $feed; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Escaped service projection. ?></section>
            <section id="chat-composer" class="pch-compose-panel">
                <?php if ( $can_compose ) : ?>
                    <header><p class="pch-eyebrow"><?php echo esc_html( $thread ? __( 'Join in', 'petish-passport' ) : __( 'Your corner of the conversation', 'petish-passport' ) ); ?></p><h2><?php echo esc_html( $thread ? __( 'Add your reply', 'petish-passport' ) : __( 'What’s on your mind?', 'petish-passport' ) ); ?></h2></header>
                    <form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" data-chat-composer>
                        <input type="hidden" name="action" value="<?php echo $thread ? 'petish_chat_create_reply' : 'petish_chat_create_topic'; ?>"><input type="hidden" name="request_id" value="<?php echo esc_attr( $state['form']['request_id'] ); ?>">
                        <?php if ( $thread ) : ?><input type="hidden" name="topic_id" value="<?php echo (int) $thread['id']; ?>"><input type="hidden" name="parent_id" value="<?php echo esc_attr( $state['form']['parent_id'] ?? '0' ); ?>"><div class="pch-reply-target" data-chat-reply-target <?php if ( empty( $state['reply_to'] ) ) echo 'hidden'; ?>><span data-chat-reply-label><?php if ( ! empty( $state['reply_to'] ) ) echo esc_html( sprintf( __( 'Replying to %s', 'petish-passport' ), $state['reply_to']['alias'] ) ); ?></span><a href="<?php echo esc_url( self::url( $filters, 'chat-composer' ) ); ?>" data-chat-reply-cancel><?php esc_html_e( 'Reply to the topic instead', 'petish-passport' ); ?></a></div><?php endif; ?>
                        <?php wp_nonce_field( self::nonce_action( $thread ? 'create_reply' : 'create_topic', $thread['id'] ?? 0 ), self::NONCE_FIELD, false ); ?>
                        <div class="pch-compose-fields"><label for="petish-chat-alias"><?php esc_html_e( 'Public name', 'petish-passport' ); ?><input id="petish-chat-alias" name="alias" value="<?php echo esc_attr( $state['form']['alias'] ); ?>" maxlength="40" required autocomplete="off" aria-describedby="petish-chat-identity-help"></label>
                        <?php if ( ! $thread ) : ?><label for="petish-chat-channel"><?php esc_html_e( 'Channel', 'petish-passport' ); ?><select id="petish-chat-channel" name="channel" required><?php foreach ( $state['channels'] as $slug => $label ) : ?><option value="<?php echo esc_attr( $slug ); ?>" <?php selected( $state['form']['channel'], $slug ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label><?php endif; ?></div>
                        <p id="petish-chat-identity-help" class="pch-field-help"><?php esc_html_e( 'This name and your message will be public. Use a name you are comfortable sharing.', 'petish-passport' ); ?></p>
                        <?php if ( ! $thread ) : ?><fieldset class="pch-post-kind"><legend><?php esc_html_e( 'I’d like to…', 'petish-passport' ); ?></legend><label><input type="radio" name="kind" value="question" <?php checked( $state['form']['kind'], 'question' ); ?>><?php esc_html_e( 'Ask a question', 'petish-passport' ); ?></label><label><input type="radio" name="kind" value="discussion" <?php checked( $state['form']['kind'], 'discussion' ); ?>><?php esc_html_e( 'Start a conversation', 'petish-passport' ); ?></label></fieldset><label for="petish-chat-title"><?php esc_html_e( 'Give it a title', 'petish-passport' ); ?><input id="petish-chat-title" name="title" maxlength="120" required value="<?php echo esc_attr( $state['form']['title'] ); ?>"></label><?php endif; ?>
                        <label for="petish-chat-body"><?php echo esc_html( $thread ? __( 'Your reply', 'petish-passport' ) : __( 'Your message', 'petish-passport' ) ); ?><textarea id="petish-chat-body" name="body" rows="5" maxlength="4000" required aria-describedby="petish-chat-posting-help"><?php echo esc_textarea( $state['form']['body'] ); ?></textarea></label>
                        <label class="pch-consent"><input type="checkbox" name="consent" value="1" required><span><?php esc_html_e( 'Publish this contribution under my public name.', 'petish-passport' ); ?></span></label>
                        <div class="pch-compose-footer"><p id="petish-chat-posting-help" class="pch-field-help"><?php esc_html_e( 'Your first contribution is reviewed before it appears publicly. Keep personal and order details private.', 'petish-passport' ); ?></p><button class="pch-button" type="submit"><?php echo esc_html( $thread ? __( 'Post reply', 'petish-passport' ) : __( 'Post conversation', 'petish-passport' ) ); ?></button></div>
                    </form>
                <?php elseif ( ! $state['signed_in'] ) : ?><h2><?php esc_html_e( 'Your pet people are here.', 'petish-passport' ); ?></h2><p><?php esc_html_e( 'Everyone can read. Sign in with your Petish account to ask a question or add a reply.', 'petish-passport' ); ?></p><a class="pch-button" href="<?php echo esc_url( $login ); ?>"><?php esc_html_e( 'Sign in to join in', 'petish-passport' ); ?></a>
                <?php elseif ( $thread && ! empty( $thread['closed'] ) ) : ?><h2><?php esc_html_e( 'This conversation is closed.', 'petish-passport' ); ?></h2><p><?php esc_html_e( 'You can keep reading the replies or start another conversation.', 'petish-passport' ); ?></p><a class="pch-button pch-button-secondary" href="<?php echo esc_url( self::url( array( 'channel' => $thread['channel'] ), 'chat-composer' ) ); ?>"><?php esc_html_e( 'Start a conversation', 'petish-passport' ); ?></a>
                <?php elseif ( $thread && 'pending' === $thread['status'] ) : ?><h2><?php esc_html_e( 'A quick check before the conversation starts.', 'petish-passport' ); ?></h2><p><?php esc_html_e( 'The moderation team will review this contribution. Replies open when it is published.', 'petish-passport' ); ?></p>
                <?php else : ?><h2><?php esc_html_e( 'Posting is currently unavailable.', 'petish-passport' ); ?></h2><p><?php esc_html_e( 'You can still browse public conversations. Contact Petish if you need help with your community access.', 'petish-passport' ); ?></p><?php endif; ?>
            </section>
        </div>
    </div>
</main>
